<?php namespace App\Http\Controllers; use Illuminate\Http\Request; use App\Models\Campaign; class CalendarController{function index(){return view('calendar.index');} function events(Request $r){$q=Campaign::with('channel','topic')->where('tenant_id',session('active_tenant_id')); foreach(['topic_id','channel_id','status'] as $f) if($r->$f)$q->where($f,$r->$f); return $q->get()->map(fn($c)=>['id'=>$c->id,'title'=>$c->title,'start'=>$c->start_date?->toDateString(),'end'=>$c->end_date?->copy()->addDay()->toDateString(),'backgroundColor'=>$c->channel?->color ?: '#64748b','borderColor'=>$c->channel?->color ?: '#64748b','extendedProps'=>['status'=>$c->status,'topic'=>$c->topic?->title,'channel'=>$c->channel?->name,'url'=>route('campaigns.show',$c)]]);} function move(Request $r, Campaign $campaign){abort_unless($campaign->tenant_id==session('active_tenant_id'),403);$d=$r->validate(['start_date'=>'required|date','end_date'=>'nullable|date']);$campaign->update($d);return response()->json(['ok'=>true]);}}
